DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname='page_component_artefact_archive') THEN RAISE EXCEPTION 'mig552: 357 not applied'; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='page_components'::regclass AND tgname='trg_page_component_artefact_archive_upd') THEN RAISE EXCEPTION 'mig552: 357 UPDATE trigger missing'; END IF;
  IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='page_components'::regclass AND tgname='trg_page_component_content_archive_upd') THEN RAISE EXCEPTION 'mig552: already applied'; END IF;
END $$;
CREATE TRIGGER trg_page_component_content_archive_upd
AFTER UPDATE OF content_data ON page_components FOR EACH ROW
WHEN (OLD.content_data IS NOT NULL AND OLD.content_data <> '{}'::jsonb
      AND NEW.content_data IS DISTINCT FROM OLD.content_data
      AND NEW.rendered_html IS NOT DISTINCT FROM OLD.rendered_html)
EXECUTE FUNCTION page_component_artefact_archive();
